package android.graphics;import android.os.*;import android.opengl.FakeGpu;public class SurfaceTexture{public interface OnFrameAvailableListener{void onFrameAvailable(SurfaceTexture s);}public volatile boolean released;public long pendingTimestamp,timestamp;public int updates;private OnFrameAvailableListener listener;private Handler handler;public final int texture;public SurfaceTexture(int t){texture=t;FakeGpu.latestTexture=this;}public void setOnFrameAvailableListener(OnFrameAvailableListener l){listener=l;}public void setOnFrameAvailableListener(OnFrameAvailableListener l,Handler h){listener=l;handler=h;}public void setDefaultBufferSize(int w,int h){}public void updateTexImage(){FakeGpu.current();synchronized(FakeGpu.updateLock){if(FakeGpu.blockUpdate)FakeGpu.blockedUpdates.incrementAndGet();while(FakeGpu.blockUpdate)try{FakeGpu.updateLock.wait();}catch(InterruptedException e){throw new AssertionError(e);}}if(FakeGpu.surface.get().window==null)FakeGpu.pbufferUpdates.incrementAndGet();else FakeGpu.windowUpdates.incrementAndGet();if(FakeGpu.failUpdate)throw new IllegalStateException("synthetic update failed");if(released)throw new IllegalStateException("released");timestamp=pendingTimestamp;updates++;FakeGpu.consumed.incrementAndGet();}public long getTimestamp(){return timestamp;}public void getTransformMatrix(float[] m){java.util.Arrays.fill(m,0);m[0]=m[5]=m[10]=m[15]=1;}public void release(){released=true;}public void emit(long pts){pendingTimestamp=pts;final OnFrameAvailableListener l=listener;if(l!=null){if(handler==null)l.onFrameAvailable(this);else handler.post(()->l.onFrameAvailable(this));}}}

